import { useState, useEffect, useRef } from "react";

function Home() {
  const [inputValue, setInputValue] = useState("");
  const [messages, setMessages] = useState([
    { text: "Hi! How can I help you today?", sender: "ai" }
  ]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef(null); // For auto-scrolling

  // This scrolls the chat to the bottom whenever a new message arrives
  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (inputValue.trim() === "") return;

    // 1. Add User message to the chain
    const userMsg = { text: inputValue, sender: "user" };
    setMessages((prev) => [...prev, userMsg]);
    setLoading(true);
    const currentInput = inputValue;
    setInputValue(""); 

    try {
      const response = await fetch("http://localhost:5000/api/recipe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userInput: currentInput }),
      });

      const data = await response.json();
      
      // 2. Add AI message to the chain
      const aiMsg = { text: data.response || data.Response, sender: "ai" };
      setMessages((prev) => [...prev, aiMsg]);
    } catch (err) {
      setMessages((prev) => [...prev, { text: "Error: Could not reach the chef.", sender: "ai" }]);
    }
    setLoading(false);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 p-4">
      {/* 💬 Message Display Area */}
      <div className="flex-1 overflow-y-auto mb-4 space-y-4 p-2">
        {messages.map((msg, index) => (
          <div key={index} className={`flex ${msg.sender === "user" ? "justify-end" : "justify-start"}`}>
            <div className={`max-w-[80%] p-3 rounded-2xl shadow-sm ${
              msg.sender === "user" 
                ? "bg-blue-600 text-white rounded-br-none" 
                : "bg-white text-gray-800 rounded-bl-none"
            }`}>
              <p className="text-sm">{msg.text}</p>
            </div>
          </div>
        ))}
        {loading && <p className="text-xs text-gray-400 italic">Chef is typing...</p>}
        <div ref={scrollRef} /> {/* Hidden div to anchor scrolling */}
      </div>

      {/* ⌨️ Input Box */}
      <form onSubmit={handleSubmit} className="w-full max-w-2xl mx-auto flex gap-2">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          className="flex-1 border border-gray-300 rounded-full px-6 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-md"
          placeholder="Ask for a recipe..."
        />
        <button type="submit" className="bg-blue-600 text-white p-3 rounded-full hover:bg-blue-700 transition shadow-md">
          Send
        </button>
      </form>
    </div>
  );
}

export default Home;
